/* bcal.js — Bengali (Bangabda) date as used in West Bengal, for 1433–1434.
 *
 * West Bengal follows the traditional Panjika (Surya Siddhanta sun), not the
 * revised Bangladesh calendar, so month lengths change every year (29–32 days)
 * and cannot be generated by a fixed rule. The month start dates below were
 * checked three ways (Oct 2026):
 *   1. bengalicalendarnow.com, full year 1433 (cites Benimadhab Seal Full Panjika)
 *   2. bengalicalendar.com, month by month, "for Kolkata, West Bengal"
 *   3. our own Surya Siddhanta sankranti calculation with the West Bengal
 *      midnight rule (sankranti before local midnight → month starts next day;
 *      after midnight → the day after).
 * Every month where (1) and (2) agree matches (3); where they disagree, (3) is
 * used. 1434 comes from (3) only; no 1434 sankranti falls within an hour of
 * midnight, so none is borderline. Outside the table, bengaliDate() returns null
 * and the app shows the English date only.
 *
 * The Bengali day traditionally starts at sunrise; like most printed and digital
 * calendars, this uses the civil (midnight) date.
 * Somdeep Kundu, RuDRA Lab, C-TARA, IIT Bombay · MIT */
(function (root) {
  'use strict';
  const MONTHS = [
    ['বৈশাখ', 'Boishakh'], ['জ্যৈষ্ঠ', 'Joishtho'], ['আষাঢ়', 'Asharh'], ['শ্রাবণ', 'Shrabon'],
    ['ভাদ্র', 'Bhadro'], ['আশ্বিন', 'Ashwin'], ['কার্তিক', 'Kartik'], ['অগ্রহায়ণ', 'Ogrohayon'],
    ['পৌষ', 'Poush'], ['মাঘ', 'Magh'], ['ফাল্গুন', 'Falgun'], ['চৈত্র', 'Choitro']
  ];
  // Six seasons, two months each, starting with Boishakh.
  const RITU = [['গ্রীষ্ম', 'Grishmo'], ['বর্ষা', 'Borsha'], ['শরৎ', 'Shorot'], ['হেমন্ত', 'Hemonto'], ['শীত', 'Sheet'], ['বসন্ত', 'Bosonto']];
  const DAYS = ['রবিবার', 'সোমবার', 'মঙ্গলবার', 'বুধবার', 'বৃহস্পতিবার', 'শুক্রবার', 'শনিবার'];
  // 1st of each month, Boishakh → Choitro.
  const STARTS = {
    1433: ['2026-04-15', '2026-05-16', '2026-06-16', '2026-07-18', '2026-08-18', '2026-09-19',
           '2026-10-19', '2026-11-18', '2026-12-17', '2027-01-16', '2027-02-14', '2027-03-16'],
    1434: ['2027-04-15', '2027-05-16', '2027-06-17', '2027-07-18', '2027-08-19', '2027-09-19',
           '2027-10-19', '2027-11-18', '2027-12-18', '2028-01-16', '2028-02-14', '2028-03-15']
  };
  const LAST_VALID = '2028-04-13';   // 1 Boishakh 1435 is 14 or 15 Apr 2028 (borderline); stop before it

  const BN = '০১২৩৪৫৬৭৮৯';
  const bnNum = n => String(n).replace(/\d/g, d => BN[d]);
  const dayNo = iso => Math.round(Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10)) / 864e5);
  // civil date in India, whatever the phone's own time zone is set to
  function istISO(d) {
    const t = new Date(d.getTime() + 5.5 * 3600e3);
    return t.toISOString().slice(0, 10);
  }

  function bengaliDate(date) {
    const d = date || new Date(), iso = istISO(d);
    if (iso < STARTS[1433][0] || iso > LAST_VALID) return null;
    const n = dayNo(iso);
    let year = null, m = -1;
    for (const y of [1433, 1434]) STARTS[y].forEach((s, i) => { if (dayNo(s) <= n) { year = y; m = i; } });
    const day = n - dayNo(STARTS[year][m]) + 1;
    const wd = new Date(Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10))).getUTCDay();
    const ritu = RITU[Math.floor(m / 2)];
    return {
      year, month: m + 1, day,
      bn: `${bnNum(day)} ${MONTHS[m][0]} ${bnNum(year)}`,
      en: `${day} ${MONTHS[m][1]} ${year}`,
      monthBn: MONTHS[m][0], monthEn: MONTHS[m][1],
      rituBn: ritu[0], rituEn: ritu[1], weekdayBn: DAYS[wd]
    };
  }
  root.BCal = { bengaliDate, bnNum, STARTS, LAST_VALID };
  if (typeof module !== 'undefined') module.exports = root.BCal;
})(typeof self !== 'undefined' ? self : this);
